contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address recipient) public payable {
        require(address(this).balance >= 1);

        // Provide c with some ether it can later withdraw.
        (bool sent,) = address(c).call{value: 1}('');
        require(sent);

        uint256 balanceBefore = address(c).balance;

        address ownerAddr = c.owner();
        bool reverted;
        uint256 recipientBefore = recipient.balance;

        if (caller == ownerAddr) {
            // Owner can withdraw; it is a state-changing call, so top-level.
            c.withdrawAll(recipient);
            reverted = false;
        } else {
            // Non-owner must revert; use try/catch to still reach assert instead of aborting.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (caller == ownerAddr) {
            assert(!reverted && address(c).balance == 0 && recipient.balance == recipientBefore + balanceBefore);
        } else {
            assert(reverted && address(c).balance == balanceBefore && recipient.balance == recipientBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address recipient, uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Give c some ether so there is something to withdraw.
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 balanceBefore = address(c).balance;
        uint256 recipientBefore = recipient.balance;
        address ownerAddr = c.owner();

        // If the caller is the owner, make the successful withdrawal call as a top-level statement.
        if (caller == ownerAddr) {
            c.withdrawAll(recipient);
        }

        bool reverted;
        if (caller != ownerAddr) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false;
        }

        if (caller == ownerAddr) {
            assert(address(c).balance == 0 && recipient.balance >= recipientBefore + balanceBefore);
        } else {
            assert(reverted && address(c).balance == balanceBefore && recipient.balance == recipientBefore);
        }
    }
}

